<div class="card divide-y divide-line">@foreach($vm->units() as $unit)@php($rows=array_values(array_filter($vm->people(),fn($p)=>$p['unit']===$unit['id'])))<div class="flex flex-wrap items-center gap-5 p-5"><div class="min-w-[185px] grow"><strong class="font-semibold">{{ $unit['nama'] }}</strong><p class="mt-1 text-xs text-muted">{{ $unit['kepala'] }}</p></div><div class="min-w-[180px] grow"><div class="flex h-1.5 overflow-hidden rounded-full bg-subtle">@foreach(['Final'=>'bg-success','Diajukan'=>'bg-info','Dikembalikan'=>'bg-warning','Draft'=>'bg-gray-400'] as $status=>$color)@php($count=count(array_filter($rows,fn($p)=>$p['status']===$status)))<span class="{{ $color }}" style="width:{{ count($rows)?$count/count($rows)*100:0 }}%"></span>@endforeach</div><p class="mt-2 text-xs text-muted">{{ count(array_filter($rows,fn($p)=>$p['status']==='Diajukan')) }} menunggu, {{ count(array_filter($rows,fn($p)=>$p['status']==='Final')) }} Final, {{ count(array_filter($rows,fn($p)=>in_array($p['status'],['Belum','Draft','Dikembalikan'])) ) }} belum diajukan</p></div>@if($vm->role==='hc')<button class="btn btn-ghost btn-small" data-action="remind" data-unit="{{ $unit['nama'] }}" type="button">Kirim pengingat</button>@else<a class="link" href="{{ $vm->link('persetujuan') }}&unit={{ $unit['id'] }}">Lihat pengajuan</a>@endif</div>@endforeach</div>
